      q: 'Identify whether each statement about inputs and outputs is correct.',
      labels: ['Correct', 'Not correct'],
      statements: [
        { text: 'Output tax is the VAT a business charges on its sales.', answer: true },
        { text: 'Input tax is the VAT a business is charged on its purchases.', answer: true },
        { text: 'Outputs are the VAT charged rather than the value of the sales.', answer: false },
        { text: 'A business always pays HMRC the whole of its output tax.', answer: false },
      ],
      exp: 'Inputs and outputs are values; input tax and output tax are the VAT on them. What goes to HMRC is the difference between the two taxes, which is why a business recovering more than it charges receives a repayment instead of making a payment.',
